INSERT INTO public.operational_plans (id, calculation_id, forest_name, sections, plan_metadata, status, created_at, updated_at, submitted_at, approved_at, created_by, approved_by) VALUES ('c24a8790-ae91-4f92-b30e-a2c4326531b8', '316103c3-22ab-4a50-9620-79261f6b8be7', 'टुन्दरपुर', '{"tree": [{"id": "0961ef3c-d427-4e75-a787-a7d39276fb19", "type": "preamble", "level": 0, "number": null, "content": "लिखितम् {{district}} जिल्ला {{forest_municipality}} {{forest_municipality_type}} वडा नं. {{forest_ward}} स्थित {{forest_name}} सामुदायिक वन उपभोक्ता समूहको तर्फबाट अख्तियारी प्राप्त हामी {{municipality}} {{municipality_type}} वडा नं. {{ward}} मा पर्ने {{forest_name}} सा. व. पूर्वमा {{cf_boundary_east}}, पश्चिममा {{cf_boundary_west}}, उत्तरमा {{cf_boundary_north}}, दक्षिणमा {{cf_boundary_south}}, यति चार किल्ला भित्रको {{cf_area_provided}} हेक्टर क्षेत्रफल भएको राष्ट्रिय वन वन ऐन, २०७६, वन नियमावली, २०७९ र बागमती प्रदेशको वन ऐन, २०७६ र बागमती प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}} को अधिनमा रही स्वीकृत वन कार्ययोजना अनुरुप तपशिलका सर्तहरु बमोजिम सामुदायिक वनको रुपमा जिम्मा लिई वनको विकास, संरक्षण, व्यवस्थापन तथा सदुपयोग गर्न मञ्जुर छौँ । कवुलियत बमोजिमको शर्त पालना नगरेमा प्रचलति कानून बमोजिम सहुँला बुझाँउला भनी खुसीराजीसँग यो कबुलियतनामा लेखी डिभिजन वन कार्यालय, {{division}} मार्फत नेपाल सरकारमा चढायौँ ।\nतपसिल\n१. स्वीकृत कार्ययोजनामा उल्लेख भए बाहेक अन्य काम कारवाही गर्ने छैन । \n२. आफुले सामुदायिक वनको रुपमा पाएको वनक्षेत्र लगायत अन्य वनक्षेत्रमा अतिक्रमण वा अन्य कुनै प्रकारले हानी नोक्सानी गर्ने गराउने छैनौ । \n३. डिभिजन वन कार्यालय र सव-डिभिजन वन कार्यालयले दिएको सल्लाह र सुझाव अनुरुप कार्य गर्नेछौ। \n४. आर्थिक वर्ष समाप्त भएको ३ महिना भित्र तोकिएको ढाचामा वार्षिक प्रतिवेदन सव डिभिनज वन कार्यालय मार्फत डिभिजन वन कार्यलयमा पेश गर्नेछौ ।\n५. वन उपभोक्ता समूहले कार्ययोजना बमोजिम काम गर्न नसकेमा वा कार्ययोजना विपरित काम गरेमा वा वातावरणमा उल्लेखनीय प्रतिकुल असर पर्ने कुनै कार्य गरेको वा वन ऐन वा वन नियमावली तथा नेपाल सरकारले तोकेको शर्तहरु पालना नगरेको प्रमाणित हुन आएमा ऐन नियम बमोजिम कारवाही गरेमा हाम्रो मन्जुरी छ । \n६. सामुदायिक वनभित्र वन विकास कार्यबाहेक अन्य कुनै सार्वजनिक विकास निर्माणका कार्यहरु जस्तै सडक, स्कूल, खानेपानी, सिंचाई कुलो आदि संचालन गर्नुपर्दा वातावरणमा उल्लेखनीय प्रतिकुल असर नपर्ने गरी नेपाल सरकारको पूर्व स्वीकृति लिएर मात्र संचालन गरिने छ । \n७. राष्ट्रिय निकुञ्ज तथा वन्य जन्तु संरक्षण ऐन, २०२९ को विपरित हुने गरी कुनै वन्यजन्तु पक्रने वा मारिने छैन, यदि कोहीकसैले त्यस्तो कार्य गरे गराएमा कसुरदारलाई पक्राउ गर्न सहयोग गरिनेछ । \n८. सामुदायिक वन सम्बन्धी क्रियाकलापको स्थलगत निरीक्षणको कार्यमा आउने वन कर्मचारीलाई आवश्यक सहयोग गर्नेछौ । \n९.यो सामुदायिक वन हस्तान्तरण हुनु पूर्व नेपाल सरकार र अरु अन्य संघ/संस्था बीच सम्झौता भई\nलागु भईरहेको साविक भोगचलनलाई सो अवधिभर यो हस्तान्तरणले कुनै असर नपार्ने कुरामा सहमत छौ।\n१०. सामुदायिक वनको प्रमाण-पत्र हराएमा, च्यातिएमा वा नासिएमा अर्को लिन रु. २५।- दस्तुर तिर्न मञ्जुर छौँ।  \n१२. कार्ययोजना संशोधन गर्दा वातावरणमा उल्लेखनिय प्रतिकुल असर पर्ने गरी गर्नेछैनौ ।\n१२.वनक्षेत्रको भू-स्वामित्व नेपाल सरकारमा रहनेछ । तर यसको संरक्षण गर्ने दायित्व उपभोक्ता समूहको हुनेछ ।\n१३.सामुदायिक वनको विकास, संरक्षण, संवर्धनको लागि आवश्यक प्राविधिक सहयोग डिभिजन वन कार्यालय, सव-डिभिजन वन कार्यालय वा अन्य सहयोगी संस्था र समूह भित्र रहेका प्राविधिकहरुबाट लिनेछौँ ।\n१४.सामुदायिक वनबाट स्विकृत कार्ययोजना बमोजिम प्राप्त हुने वन पैदावार मात्र वन उपभोक्ता समूह भित्र समतामूलक रुपमा विक्री वितरण गर्नेछौँ ।\n१५.सामुदायिक वनमा मुख्य वनपैदावारको घनत्व र उत्पादनमा ह्रास नआउने गरी अन्नबाली बाहेकका लामो समयसम्म एउटै बोटले उत्पादन लिन सकिने खालका बाँस, अम्रिसो र जडिबुटी जस्ता अन्य नगदेबाली मात्र कार्ययोजनामा उल्लेख भएको हकमा लगाउनेछौँ ।\n१६. वन कार्ययोजनामा उल्लेख भएका वन संबर्धन तथा व्यवस्थापनका क्रियाकलापहरु गर्दा प्राप्त हुने वन पैदावार मात्र संकलन गरिने छ, यस बाहेक बढी परिमाणको काठ कुनैपनि हालतमा काट्ने छैनौ ।\n१७. वन कार्ययोजनामा वन सम्बन्धी कार्यहरु संशोधन गर्नु परेको अवस्थामा साधारण सभाको बैठकमा वन प्राविधिकलाई आमन्त्रित गर्ने छौँ ।\n१८. समूहले वन विकास र सामाजिक विकासका क्रियाकलापको आवश्यकता महशुस गरेमा अन्य संघसंस्थासँग समन्वय गरी सहयोग लिन सक्नेछ ।\n१९. कुनै किसिमका तालिम, गोष्ठी, सेमिनार र भ्रमणमा सहभागी पठाउँदा इच्छुक तथा बिषयगत दक्षता भएकालाई सहभागी गराउनेछौँ ।\n२०. साधारणतया वन कार्ययोजना तयार भई लागू भएको कम्तिमा दुई वर्ष नभई परिमार्जन गरिने छैन। यदि सो अवधि भित्र बिशेष परिस्थिति परी कार्ययोजनाको परिमार्जन गर्नु परेमा साधारण सभाको दुई तिहाई बहुमतबाट पारित गर्नुपर्ने छ ।\n२१. वन उपभोक्ता समूहका पदाधिकारीहरुले वन ऐन, २०७६ र वन नियमावली, २०७९, बागमती प्रदेश राष्ट्रिय वन ऐन, २०७६ र समूहको विधान कार्ययोजना बिपरित काम कार्वाही गरेमा ऐन नियम बमोजिम सजाय भएमा हाम्रो मञ्जुर छ ।\n२२. वन ऐनमा उल्लेख भए बमोजिम कार्ययोजना अनुसार प्राप्त भएको आम्दानीको कम्तीमा ४०% रकम अनिवार्य रुपमा वनको संरक्षण, विकास र व्यवस्थापनको लागि खर्च गर्नेछौँ ।\n२३. नेपाल सरकारको हरेक ऐन, नियम, नीति, निर्देशिका तथा परिपत्रहरुको पूणर्रुपमा पालना गर्नेछौँ ।\n\n{{district}} जिल्ला {{municipality}} {{municipality_type}} वडा नं. {{ward}} स्थित {{forest_name}} सामुदायिक वन उपभोक्ता समूहको तर्फबाट :\n{{uc_members}}\n{{kabuliyatnama_date_sentence}}\n", "deleted": false, "children": [], "map_type": null, "table_id": null, "title_en": "Kabuliyatnama", "title_ne": "कबुलियतनामा", "is_locked": false, "chart_type": null, "content_type": "richtext", "static_table": null, "last_modified": "2026-07-01T10:10:32.200448", "hidden_in_export": false}, {"id": "b325f611-a734-414b-bf6d-a3d0f459423f", "type": "preamble", "level": 0, "number": null, "content": "संक्षिप्त शव्दहरुको सूची (List Of Acronyms)\n\nडि.व.का.\t\t\t\tडिभिजन वन कार्यालय\nस.डि.व.का.\t\t\t\tसव डिभिजन वन कार्यालय\nक्यू.फि.\t\t\t\tक्युविक फिट\nक्यू.मि.\t\t\t\tक्युविक मिटर\nगै.का.व.पै.\t\t\t\tगैह्र काष्ठ वन पैदावार\nघ.मि.\t\t\t\tघन मिटर\nमि.\t\t\t\tमिटर\nमे.टन\t\t\t\tमेट्रिक टन\nसा.ब.उ.स./समिति\t\t\tसामुदायिक वन उपभोक्ता समुह/ समिति\nहे.\t\t\t\tहेक्टर\nगा.पा./न.पा.\t\t\t\tगाँउपालिका, नगरपालिका\n4D\t\t\t\tमरेको, सुकेको, रोग लागेको र मकिएको \nGIS\t\t\t\tGeoghraphical Informatuion System\nGPS\t\t\t\tGlobal Position System\nAg\t\t\t\tAdvance Grouth\nB\t\t\t\tब्लक\nFC\t\t\t\tFelling Cycle \nFS\t\t\t\tFelling Series \nST\t\t\t\tSlope Tree (भिरालोमा परेको रुख_\nFT\t\t\t\tFelling Tree (कटान रुख_\nCT\t\t\t\tConservation Tree\nAdg\t\t\t\tAdvance growth\n", "deleted": false, "children": [], "map_type": null, "table_id": null, "title_en": "Glossary", "title_ne": "शब्दावली परिचय", "is_locked": false, "chart_type": null, "content_type": "richtext", "static_table": null, "last_modified": null, "hidden_in_export": false}, {"id": "fd2bf303-198b-4d48-b31f-0c64455f06dc", "type": "preamble", "level": 0, "number": null, "content": "पेश गर्ने :\nउपरोक्त विषयमा {{forest_name}} सामुदायिक वनको संरक्षण, संवर्द्धन र सदुपयोग गर्न वन प्राविधिकको सहयोगमा समूहका सदस्यहरुको सक्रिय सहभागितामा तयार पारिएको दिगो वन व्यवस्थापन कार्ययोजना समूहको मिति {{op_general_assembly_date}} मा बसेको गणपुरक संख्या पुगेको साधारण सभामा प्रस्तुत भई व्यापक छलफल तथा विचार विमर्श गरी तयार गरी पारित गरिएको श्री  {{forest_name}} सामुदायिक वन, {{municipality}} {{municipality_type}}-{{ward}} को दिगो वन व्यवस्थापन कार्ययोजना, {{op_preparation_year}} स्वीकृतिको लागि सिफारिस गरी दिनहुन संलग्न राखि पेश गरेका छौं ।\nउपभोक्ता समुहको तर्फबाट\nनाम :  {{cf_chairperson}}\nपद : अध्यक्ष\nदस्तखत :\nमिति :{{kabuliyatnama_date}}\n\nसिफारिस गर्ने :\nयसमा उपरोक्त बमोजिमको वन कार्ययोजना वन ऐन, २०७६, वन नियमावली, २०७९ तथा प्रदेश राष्ट्रिय वन ऐन, २०७६, वन श्रोत सर्वेक्षण २०६१ (परिमार्जन),  सामुदायिक वनको मार्गदर्शन २०७१ (संशोधित) तथा {{province}} प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}} र विभागले तोकेका सर्त र निर्देशनको परिधि भित्र रही तयार भएको हुँदा पेश हुन आएको श्री  {{forest_name}} सामुदायिक वन, {{forest_municipality}} {{forest_municipality_type}}-{{forest_ward}} को दिगो वन व्यवस्थापन कार्ययोजना, {{op_preparation_year}} स्वीकृत गरी दिनु हुन सिफरिस साथ पेश गरेको छु ।\nसव डिभिजन वन कार्यालय {{sub_division}}को तर्फबाट\nनाम : {{sub_division_chief}}\nपद : वन अधिकृत\nदस्तखत :\nमिति :{{kabuliyatnama_date}}\n\n\n\nचेक जाँच गर्ने :\nयसमा श्री सव डिभिजन वन कार्यालय {{sub_division}}बाट सिफरिस साथ प्राप्त हुन आएको  {{forest_name}} सामुदायिक वनको वन व्यवस्थापन कार्ययोजनालाई विस्तृत अध्ययन गर्दा वन ऐन, २०७६, वन नियमावली, २०७९ तथा प्रदेश राष्ट्रिय वन ऐन, २०७६, वन श्रोत सर्वेक्षण २०६१ (परिमार्जन), सामुदायिक वनको मार्गदर्शन २०७१ (संशोधित) तथा {{province}} प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}} र विभागले तोकेका सर्त र निर्देशनको परिधि भित्र रही तयार भएको हुँदा पेश हुन आएको श्री  {{forest_name}} सामुदायिक वन, {{forest_municipality}} {{forest_municipality_type}}-{{forest_ward}} को दिगो वन व्यवस्थापन कार्ययोजना, {{op_preparation_year}} स्वीकृत गरी दिनु हुन मनासिव देखि पेश गरेको छु ।\nवन व्यवस्थापन शाखाको तर्फबाट\nनाम : {{forest_management_section_chief}}\nपद : वन अधिकृत \nदस्तखत :\nमिति :{{kabuliyatnama_date}}\n\nस्वीकृत गर्ने :\nयसमा उपरोक्त बमोजिमको वन व्यवस्थापन कार्ययोजना, २०८१ समुहबाट तयार गरी सव डिभिजन वन कार्यालय {{sub_division}}बाट सिफारिस भई वन व्यवस्थापन शाखाबाट चेकजाँच भएको उक्त वनको परिमार्जित वन कार्ययोजना वन ऐन, २०७६ र वन नियमावली, २०७९, प्रदेश राष्ट्रिय वन ऐन, २०७६ तथा बागमती प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}} र विभागले तोकेका सर्त र निर्देशनको परिधि भित्र रही सो बमोजिम पेश हुन आएकोले श्री  {{forest_name}} सामुदायिक वन, {{forest_municipality}} {{forest_municipality_type}}-{{forest_ward}} को वन व्यवस्थापन कार्ययोजना, {{op_preparation_year}} {{province}} प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}}बमोजिम स्वीकृत गरिएको छ ।\nडिभिजन वन कार्यालय {{division}}को तर्फबाट\nनाम : {{division_forest_officer}}\nपद : डिभिजनल वन अधिकृत \nदस्तखत :\nमिति:{{kabuliyatnama_date}}", "deleted": false, "children": [], "map_type": null, "table_id": null, "title_en": "Approval", "title_ne": "वन कार्ययोजना स्वीकृति", "is_locked": false, "chart_type": null, "content_type": "richtext", "static_table": null, "last_modified": "2026-07-01T10:59:01.596375", "hidden_in_export": false}, {"id": "b4745a45-7c54-4e86-b4c7-0ede789d302a", "type": "preamble", "level": 0, "number": null, "content": "वन ऐन २०४९, वन नियमावली २०५१ र {{province}} प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}} बमोजिम {{forest_name}} सामुदायिक वनको कार्ययोजना तयार गरी वन व्यवस्थापन गर्दै आएकोमा वन ऐन, २०७६ तथा वन नियमावली, २०७९ र {{province}} प्रदेश राष्ट्रिय वन ऐन, २०७६ तथा {{province}} प्रदेशको दिगो वन व्यवस्थापन कार्यविधि, {{province_guideline_year}} को प्रावधान अनुसार वन व्यवस्थापन कार्ययोजना संसोधन गरी कार्यान्वयन गर्नुपर्ने व्यवस्था भएकोले वन सम्पदाको दीगो व्यवस्थापन स्थानीय उपभोक्ताबाटै गर्ने भन्ने नेपाल सरकार तथा {{province}} प्रदेश सरकारको नीति अनुरुप {{district}} जिल्ला {{forest_municipality}} {{forest_municipality_type}}-{{forest_ward}} मा रहेको {{cf_area_provided}} हेक्टर क्षेत्रफलमा फैलिएको राष्ट्रिय वनलाई {{forest_name}} सामुदायिक वनको रुपमा व्यवस्थापन गर्दै आएकोमा दिगो वन व्यवस्थापन गर्न, समूहको कोषबाट वन विकास तथा सामुदायिक र सामाजिक विकास गर्न, गरीब र महिलाहरुलाई सशक्त गराई निर्णय प्रकृयामा सक्रिय सहभागी गराउन, वनको वन संबर्धन प्रणालीमा आधारित वन व्यवस्थापन मार्फत वनको हैसियतमा सुधार गरी वातावरणिय लाभ प्राप्त गर्न, वन पैदावारको सततः उत्पादन र आपूर्ति गर्न, स्थानीय स्तरमा रोजगारीका अवसरहरु सृजना गरी गरिबी न्युनिकरणमा टेवा पुर्याउन र खास गरी प्रविधिको प्रयोग मार्फत सामुदायिक वन लगायत वन क्षेत्रको सुशासन अभिबृद्दी गर्न यो श्री {{forest_name}} सामुदायिक वनको कार्ययोजना वन प्राविधिकको सहयोगमा समूहले दिगो वन व्यवस्थापनको लागि उपयुक्त हुने किसिमले संसोधन गरी तयार पारिएको छ । ", "deleted": false, "children": [], "map_type": null, "table_id": null, "title_en": "Preface", "title_ne": "प्रस्तावना", "is_locked": false, "chart_type": null, "content_type": "richtext", "static_table": null, "last_modified": "2026-07-01T11:37:12.504026", "hidden_in_export": false}, {"id": "4308f532-5420-49e0-8310-e711af65d15f", "type": "preamble", "level": 0, "number": null, "content": "________________________________________\n१. सामूदायिक वन उपभोक्ता समुह सम्बन्धी जानकारी\nडिभिजन वन कार्यालय \t: हेटौडा\nसव डिभिजन वन कार्यालय   \t: फापरबारी \nसमूहको नाम\t\t    \t: श्री अमृता सामुदायिक वन उपभोक्ता समूह  \nठेगाना \t\t\t    \t: बागमती गाउँपालिका वडा नं. ०८, कुवापानी, मकवानपुर\nसमूहको कोड नं.\t\t: MAK/PH/42/33\nजम्मा घरधुरी संख्या \t    \t: १७७\nविधान स्वीकृति वर्ष      \t: २०६६/०२/२०\nसमूह दर्ता नं.\t\t\t: ३२८\nजनसंख्या \t\t      :  जम्मा ६१२ जना\nसमिति संख्या\t\t    \t: ११ (महिला ७ र पुरुष ४)\n\n२. सामूदायिक वन व्यावस्थापन सम्बन्धी जानकारी\nसामुदायिक वनको नाम \t: अमृता सामुदायिक वन  \nकार्ययोजना हस्तान्तरण मिति \t: २०६६/०२/२०\nक्षेत्रफल\t: ४०१.७१६ हे.\nउत्पादनशील क्षेत्रफल \t: ३१४.१०६ हे.\nसंरक्षित क्षेत्र\t: ८७.६५ हे.\nवनको किसिम \t: प्राकृतिक \nवनको अवस्था\t: रुखको वाहुल्यता रहेको \t\nवनको औषत उमेर/अवस्था\t: ८० वर्ष \nमुख्य प्रजाति \t: साल, असना, जामुन, चिलाउने आदि  \nमुख्य गै.का.व.पै.\t:  हर्रो, वर्रो, अमला आदी   \nऔषत छत्र घनत्व \t: ७०%\nमोहडा \t: दक्षिण पूर्वी \nभिरालोपना \t: ३.५ देखि ५३ डिग्री सम्म\nमाटो \t: खैरो, कालो र बलौटे \nभू-क्षयको अवस्था \t: खोला, खोल्सी तथा खहरे र भिरालो क्षेत्रमा भू–क्षय हुन सक्ने तर हालको स्थिती सामान्य । \n\n\nसम्पुर्ण वनको औसत मौज्दात \nरुख\t: ८४.४२ क्यू.मि./हे. (४७ गोटा/हे.)   \nपोल \t: २६.५ मि./हे. (२६५ गोटा/हे.)\nलाथ्रा \t: १८१८ गोटा/हे. \t\t  \t \nबिरुवा \t: १०९४३ गोटा/हे.\nवेशल एरिया \t:  १४.८९ वर्ग.मि./हे. जसमा (पोल : ५.५१ वर्ग.मि./हे. र रुख : ९.३८ वर्ग.मि./हे.)\n\nवन व्यवस्थापन तथा वन संवर्धन प्रणाली सम्बन्धी जानकारी\n\nकम्पार्टमेन्ट संख्या M १ \t\t\tकटान–चक्र संख्या M८ वटा \nRotation Period : ८० (साल वन)\t\t\nFelling Cycle : ८\nकम्पार्टमेन्ट : \t२ कम्पार्टमेन्ट (कम्पार्टमेन्ट C1 र कम्पार्टमेन्ट C2)   \n# सम्पूर्ण वनलाई स्लोपको आधारमा २ वटा क्षेत्रमा (उत्पादनशील (०-१९ डिग्री) र संरक्षित(१९ डिग्री भन्दा माथी) विभाजन गरी उत्पादनशील क्षेत्रलाई २ कम्पार्टमेन्ट (कम्पार्टमेन्ट C1 र कम्पार्टमेन्ट  C2) मा विभाजन गरी पुन: कम्पार्टमेन्ट C1 लाई ३ सव-कम्पार्टमेन्ट (C1S1, C1S2, C1S3) र कम्पार्टमेन्ट  C2 लाई ५ सव-कम्पार्टमेन्ट (C2S1, C2S2, C2S3, C2S4, C2S5))\n\nवन संवर्द्धन प्रणाली : कटान चक्र सहितको एकल रुख छनोट प्रणाली कम्पार्टमेन्ट C1 मा\n\t     Physical rotation कम्पार्टमेन्ट C2 मा    \nयोजना अवधि : १० बर्ष\nअग्नीरेखा/पहुच सडकको लम्बाई : १४१८ मिटर\nअनुमानित कटान प्रति वर्ष : ४०८४.१५ क्यू.फिट काठ र ९.६९ चट्टा दाउरा कम्पार्टमेन्ट C1 मा\nFloating method अनुसार\n५ मिटर र ३ मिटर फराकिलो अग्नीरेखा (आवश्यकता अनुसार थपघट गर्न सकिनेछ)।\nअन्य वन संवर्द्धन कार्यहरु : विभिन्न प्रकारको थिनिङ, सुधार कटान, झाडि सफार्इ आदि ।\n\n३. सव कम्पार्टमेन्ट अनुसार वनको मौजदात :\nसव कम्पाटमेन्ट\tक्षेत्रफल हेक्टर\tप्रति  हेक्टर विरुवा\tप्रति  हेक्टर लाथ्रा\tप्रति हेक्टर  संख्या\tप्रति  हेक्टर आयतन घ.मि.\tप्रति हेक्टर  वनको मौज्दात\n\t\tविरुवा\tअवस्था\tलाथ्रा\tअवस्था\t\tपोल\tरुख\t\n\t\tसंख्या\t\tसंख्या\t\tपोल\tरुख\t\tकाण्ड\tहाँगा\tवनको मौज्दात\nC1S1\t41.04\t9500\tराम्रो\t226\tकमसल\t371.4\t64\t41.77\t98.59\t37.75\t178.11\nC1S2\t38.57\t13529\tराम्रो\t1675\tमध्यम\t261.5\t58\t38.82\t112.08\t42.71\t193.61\nC1S3\t36.80\t14429\tराम्रो\t1288\tमध्यम\t235.7\t74\t27.26\t131.98\t50.61\t209.85\nC2S1\t36.50\t13769\tराम्रो\t1633\tमध्यम\t323.1\t62\t38.42\t82.50\t34.34\t155.26\nC2S2\t39.37\t11688\tराम्रो\t2250\tराम्रो\t275.0\t44\t40.58\t82.54\t33.06\t156.18\nC2S3\t33.25\t11455\tराम्रो\t2835\tराम्रो\t309.1\t29\t33.19\t45.13\t17.65\t95.97\nC2S4\t46.07\t12900\tराम्रो\t1720\tमध्यम\t230.0\t58\t26.86\t100.33\t37.92\t165.11\nC2S5\t42.50\t9765\tराम्रो\t1157\tमध्यम\t205.9\t36\t22.60\t64.70\t24.63\t111.93\nP.F.\t87.62\t6889\tराम्रो\t1853\tमध्यम\t236.1\t25\t30.28\t61.21\t22.76\t114.25\nजम्मा औषत\t401.72\t10943\tराम्रो\t1818\tमध्यम\t265\t47\t33.31\t86.56\t33.49\t153.36\n(पुनश्च : कम्पार्टमेन्ट C1 का ५० से.मी. ब्यास भन्दा माथीका परिपक्क रुखहरु र 4D रुखहरु मात्रै कटान गर्नको लागि योग्य रुखहरु मानिएको छ । कम्पार्टमेन्ट C2 मा ढलापडा सुखड खडा मात्रै संकलन गरिनेछ ।)\n४. प्रत्येक आ.व.मा कटान गरिने सव कम्पार्टमेन्ट र प्रजाती सहीत वार्षिक निकाल्न सकिने परिमाण :\n;fdfGo hfgsf/L\tk|lt x]S6/ tYofÍ #) ;]=ld= dfly\thDdf !) s6fg aif{df\tk|lt aif{\n\t\t\t\n;j sDkf6{d]G6\tIf]qkmn       -x]=_\td\"Vo k|hflt\t;+Vof\tsf7 3=dL=\tbfp/f 3=dL=\thDdf 3=ld\tsf7 3=dL=\tbfp/f 3=dL=\tsf7 So\"=lkm6\tbfp/f r6\\6f\tsf7 So\"