": 32645, "watershed": "Narayani Saptagandaki Watershed", "block_name": "Panchpokhari pakho", "created_at": "2026-06-29T18:00:01.840664+05:45", "forest_pct": 100.0, "forest_name": "टुन्दरपुर", "forest_ward": "५", "ug_district": "मकवानपुर", "blocks_count": 5, "completed_at": "2026-06-29T23:53:13.866201+05:45", "generated_by": "", "municipality": "हेटाैंडा", "sub_division": "हेटाैडा", "ti_available": false, "total_blocks": 5, "ug_available": false, "ya_available": false, "bio_available": false, "boundary_type": "MultiPolygon", "canopy_mean_m": 13.9, "dominant_soil": "", "export_format": "DOCX", "total_species": 9, "altitude_max_m": 732.0, "altitude_min_m": 455.0, "dominant_slope": "moderate", "forest_area_ha": 518.1216, "generated_date": "2026-06-30", "total_area_sqm": 5181215.86, "altitude_mean_m": 541.9, "aspect_dominant": "SW", "dominant_aspect": "SW", "elevation_max_m": 732.0, "elevation_min_m": 455.0, "forest_district": "मकवानपुर", "section_18_misc": "अन्य विविध व्यवस्थाहरू: ...", "ac_total_members": 0, "cf_area_provided": 518.1216, "document_version": "2.0", "elevation_mean_m": 541.9, "fc_total_members": 0, "plan_years_range": "None-None", "uc_total_members": 0, "crown_density_pct": 13.9, "document_language": "NP", "major_river_basin": "East Rapti River Basin", "municipality_type": "उ.म.न.पा.", "physiography_zone": "दुन", "section:fire_loss": "सन् २००१ देखि २०२४ सम्म यस वनको कुल ०.१८ हेक्टर (०%) क्षेत्र आगलागीबाट क्षतिग्रस्त भएको छ। आगलागी वनको लागि प्रमुख जोखिम हो, जसले वनस्पति, वन्यजन्तु र माटोको गुणस्तरमा गम्भीर असर पार्दछ।", "temperature_max_c": 22.8, "temperature_min_c": 22.1, "calculation_status": "completed", "kabuliyatnama_date": "2083/03/16", "landcover_dominant": "Tree cover", "non_forest_area_ha": 0, "section:land_cover": "यस वनको प्रमुख भू-आवरण \"Tree cover\" रहेको छ। भू-आवरणले जमिनको प्रयोग र प्राकृतिक अवस्था देखाउँदछ। यस वनमा रूख आवरण (Tree Cover), झाडी (Shrubland), घाँसे मैदान (Grassland), खेती योग्य (Cropland), बस्ती (Built-up), पानी (Water) लगायत विभिन्न प्रकारका भू-आवरणहरू पाइन्छन्।", "soil_dominant_type": "", "temperature_mean_c": 22.54, "total_plan_area_ha": 518.1216, "compartment_message": "यस सामुदायिक वनमा कुनै पनि कम्पाृ्टमेन्ट वा सव कम्पाृ्टमेन्ट तयार गरिएको छैन", "forest_municipality": "हेटाैंडा", "section:forest_loss": "सन् २००१ देखि २०२४ सम्म यस वनको कुल ३.७८ हेक्टर (०.७%) क्षेत्रमा वन क्षति भएको छ। यो जानकारी Hansen Global Forest Change डाटाबाट प्राप्त गरिएको हो। वन क्षति मुख्यतया मानवीय क्रियाकलाप, आगलागी र प्राकृतिक कारणले हुने गर्दछ।", "section:forest_type": "यस वनको प्रमुख वन प्रकार \"Shorea robusta Forest\" रहेको छ। नेपालको FRTC (Forest Resource and Training Centre) वर्गीकरण प्रणाली अनुसार यस वनमा विभिन्न प्रकारका वनहरू पाइन्छन्।", "total_area_hectares": 518.1216, "activities_available": false, "forest_gain_hectares": 0.9, "forest_loss_hectares": 3.78, "forest_type_dominant": "Shorea robusta Forest", "plan_revision_number": 1, "precipitation_max_mm": 2224.0, "precipitation_min_mm": 1945.0, "section_17_penalties": "वन अपराध सम्बन्धी सजाय: ...", "section_8_production": "वन पैदावार उत्पादन निम्नानुसार गरिनेछ...", "slope_dominant_class": "moderate", "ug_municipality_type": "उ.म.न.पा.", "canopy_dominant_class": "pole_trees", "precipitation_mean_mm": 2131.0, "protected_area_status": "संरक्षित क्षेत्र बाहीर", "section:forest_health": "यस वनको समग्र स्वास्थ्य अवस्था \"healthy\" रहेको छ, जसले कुल क्षेत्रफलको ९१.२% ओगटेको छ। वन स्वास्थ्यलाई NDVI (Normalized Difference Vegetation Index) को आधारमा पाँच वर्गमा विभाजन गरिएको छ: उत्कृष्ट (Excellent), राम्रो (Good), मध्यम (Moderate), कमजोर (Poor), र क्षरित (Degraded)।", "section:soil_analysis": "यस वनको माटोको बनावट \"बालुवे दोमट\" रहेको छ। माटोको भौतिक संरचनामा माटोको कण (Clay) २.७%, बालुवा (Sand) ४४.७%, र ग्राबेल (Silt) ५२.६% रहेको छ। माटोको pH मान ५.७ रहेको छ। माटोको उर्वराशक्ति \"Very High\" (80/100) रहेको छ। माटोको जैविक कार्बन भण्डार ०.४ t/ha रहेको छ। माटोको नाइट्रोजन १९६.७ cg/kg र CEC १५९ mmol/kg रहेको छ।", "section_16_prohibited": "सामुदायिक वनमा निम्न कार्यहरू निषेधित गरिएका छन्...", "excluded_area_hectares": 0, "fieldbook_total_points": 0, "forest_health_dominant": "healthy", "kabuliyatnama_date_day": 16, "section:forest_quality": "यस वनको प्रमुख वन गुणस्तर \"पुरानो दोस्रो पुस्ताको वन\" रहेको छ। वन गुणस्तर वितरण यस प्रकार रहेको छ: पुरानो दोस्रो पुस्ताको वन ९४.४% (परिपक्क दोस्रो पुस्ताको वन, मध्यम कार्बन), प्राथमिक वन ४.१% (पुरानो वन, सर्वाधिक कार्बन), कम उमेरको दोस्रो पुस्ताको वन १.५% (पुनरुत्थान हुँदै गरेको, कम कार्बन)।\n\nप्राथमिक वन (Primary Forest) पुरानो तथा अत्यधिक कार्बन भण्डार भएको वन हो। प्राथमिक वनले दोस्रो पुस्ताको वनको तुलनामा २ देखि ३ गुणा बढी कार्बन भण्डारण गर्न सक्दछ। यस वनको करिब २१.०४ हेक्टर क्षेत्र प्राथमिक वनले ढाकेको छ, जुन कार्बन भण्डारणको दृष्टिले अत्यन्त महत्वपूर्ण छ। यो तथ्यांक नासा (NASA/ORNL DAAC) ३० मिटर रिजोलुसनको २०२० सालको उपग्रह तथ्यांकमा आधारित छ।", "section:forest_summary": "यस वनको कुल क्षेत्रफल ५१८.१२ हेक्टर रहेको छ। यस वनमा ५ वटा वन खण्डहरू रहेका छन्। वनको औसत उचाइ ५४२ मिटर रहेको छ। कुल कार्बन भण्डार ० मेगाग्राम रहेको छ। वन स्वास्थ्य \"healthy\" अवस्थामा रहेको छ।", "section:slope_analysis": "यस वनको प्रमुख भिरालो \"मध्यम (Moderate)\" वर्ग रहेको छ, जसले कुल क्षेत्रफलको ४२.७% ओगटेको छ। भिरालोको आधारमा जमिनलाई पाँच वर्गमा बाँडिएको छ: समतल (Flat), हल्का (Gentle), मध्यम (Moderate), भिरालो (Steep), र अति भिरालो (Very Steep)। हल्का भिरालो जमिनमा सजिलै नमुना प्लट राख्न सकिन्छ भने भिरालो र अति भिरालो जमिनमा नमुना सङ्कलन गर्न कठिनाई हुन्छ।", "effective_area_hectares": 518.1216, "kabuliyatnama_date_year": 2083, "section:aspect_analysis": "यस वनको प्रमुख दिशा \"दक्षिण-पश्चिम (South-West)\" रहेको छ। दिशा (Aspect) ले भिरालो कुन दिशातिर फर्केको छ भन्ने देखाउँदछ। दक्षिणतर्फ फर्केको भिरालोमा घाम बढी लाग्छ भने उत्तरतर्फ फर्केको भिरालोमा चिसो हुन्छ।", "forest_municipality_type": "उ.म.न.पा.", "kabuliyatnama_date_month": 3, "section:canopy_structure": "यस वनको प्रमुख वन छत्र वर्ग \"पोल रूख\" रहेको छ। वन छत्रको औसत उचाइ १३.९ मिटर रहेको छ। वन छत्रले वनको संरचना र रूखको घनत्व देखाउँदछ।", "section:location_context": "यस वन बाग्मती प्रदेश, मकवानपुर जिल्ला, हेटाैंडा - वडा नं. ५ मा अवस्थित छ। यो वन Narayani Saptagandaki Watershed जलाधार र East Rapti River Basin प्रमुख नदी बेसिन अन्तर्गत पर्दछ।", "section:elevation_profile": "यस वनको औसत उचाइ ५४२ मिटर रहेको छ। न्यूनतम उचाइ ४५५ मिटर र अधिकतम उचाइ ७३२ मिटर रहेको छ। उचाइको फरक २७७ मिटर रहेको छ, जसले यस वनमा विविध वनस्पति तथा वातावरणीय अवस्था रहेको संकेत गर्दछ।", "section:species_potential": "यस वनको वन प्रकार अनुसार जम्मा ९ प्रजातिका रूखहरू सम्भावित रूपमा पाउन सकिन्छ। यस क्षेत्रमा वृक्षारोपण गर्न सकिने प्रजाती छनोट गर्दा यि प्रजातीलाइ प्राथमिकता दिन सकिन्छ।\n\nवन प्रकार अनुसार:\n• Shorea robusta Forest: 9 प्रजातिहरू\n\nभूमिका अनुसार प्रजातिहरू:\n• प्रमुख प्रजाती: Sal, Sakhu, Sakhuwa\n• सहयोगी प्रजाती: Saj, Asna, Harro, Harad, Amala, Aonla, Dhairo, Dhaukhair\n• विरलै हुने प्रजाती: Bhendre, Neem, Nim, Rajbriksha, Amaltash, Shikakai", "section_6_previous_review": "विगतको कार्ययोजनाको समीक्षा गर्दा...", "section:climate_conditions": "यस वनको वार्षिक औसत तापक्रम २२.५°C रहेको छ। वार्षिक औसत वर्षा २१३१ मिलिमिटर रहेको छ। यी मौसमी अवस्थाहरूले यस वनको वनस्पति, माटो र समग्र पारिस्थितिकी प्रणालीलाई प्रभाव पार्दछन्।", "kabuliyatnama_date_sentence": "ईति सम्वत २०८३ साल असार महिना १६ गते रोज मङ्गलबार शुभम् ।", "section:species_distribution": "यस वनमा जम्मा ९ प्रजातिका रूखहरू पाइन्छन्। यी प्रजातिहरू विभिन्न वन खण्डहरूमा फैलिएका छन्। तल प्रमुख प्रजातिहरूको सूची दिइएको छ।", "section:ti_block_area_narration": "यस सामुदायिक वनको जम्मा क्षेत्रफल ५१८.०६ हेक्टर रहेकोमा प्रभावकारी वन आवरण ५१०.०१ हेक्टर रहेको छ। बनश्रोत अप्रभावित क्षेत्र ० हेक्टर रहेको छ। ब्लक अनुसार प्रभावकारी क्षेत्रफल: पाँचपान्डव १३१.५६ हेक्टर, चतुर्भूज ६८.७८ हेक्टर, तिनकुने ८८.९९ हेक्टर, दोविल्ला १००.९२ हेक्टर, रामसिँहपाखा ११९.७५ हेक्टर रहेको छ।"}}', 'draft', '2026-06-29 23:54:11.302821+05:45', '2026-07-07 03:24:11.710398+05:45', NULL, NULL, 'dc9182dc-577f-4bbf-beae-e33875ec4515', NULL);
